        const lam = nj - old;
        p.jt = nj;
        const Px = lam * tx, Py = lam * ty;
        a.vx -= a.im * Px; a.vy -= a.im * Py; a.w -= a.iI * (p.rax * Py - p.ray * Px);
        b.vx += b.im * Px; b.vy += b.im * Py; b.w += b.iI * (p.rbx * Py - p.rby * Px);
      }
      for (let i = 0; i < n; i++) {
        const p = m.p[i];
        const dvx = b.vx - b.w * p.rby - a.vx + a.w * p.ray;
        const dvy = b.vy + b.w * p.rbx - a.vy - a.w * p.rax;
        const vn = dvx * nx + dvy * ny;
        const old = p.jn;
        let nj = old - p.nm * (vn + p.bias);
        if (nj < 0) nj = 0;
        const lam = nj - old;
        p.jn = nj;
        if (nj > p.maxJn) p.maxJn = nj;
        const Px = lam * nx, Py = lam * ny;
        a.vx -= a.im * Px; a.vy -= a.im * Py; a.w -= a.iI * (p.rax * Py - p.ray * Px);
        b.vx += b.im * Px; b.vy += b.im * Py; b.w += b.iI * (p.rbx * Py - p.rby * Px);
      }
    }
  }

  applyRestitution() {
    const thr = PHYS.restitutionThreshold, act = this.active, ev = this.events;
    for (let q = 0; q < act.length; q++) {
      const m = act[q], a = m.a, b = m.b, nx = m.nx, ny = m.ny, e = m.e;
      for (let i = 0; i < m.n; i++) {
        const p = m.p[i];
        if (p.maxJn === 0 || p.rel > -thr) continue;
        if (p.rel < -2.2 && ev.length < 48) ev.push({ x: p.px, y: p.py, s: -p.rel, a, b });
        if (e === 0) continue;
        const dvx = b.vx - b.w * p.rby - a.vx + a.w * p.ray;
        const dvy = b.vy + b.w * p.rbx - a.vy - a.w * p.rax;
        const vn = dvx * nx + dvy * ny;
        const old = p.jn;
        let nj = old - p.nm * (vn + e * p.rel);
        if (nj < 0) nj = 0;
        const lam = nj - old;
        p.jn = nj;
        const Px = lam * nx, Py = lam * ny;
        a.vx -= a.im * Px; a.vy -= a.im * Py; a.w -= a.iI * (p.rax * Py - p.ray * Px);
        b.vx += b.im * Px; b.vy += b.im * Py; b.w += b.iI * (p.rbx * Py - p.rby * Px);
      }
    }
  }

  solvePosition() {
    const beta = PHYS.baumgarte, slop = PHYS.slop, maxC = PHYS.maxCorrection, act = this.active;
    for (let q = 0; q < act.length; q++) {
      const m = act[q], a = m.a, b = m.b, R = m.flip ? b : a, I = m.flip ? a : b;
      for (let i = 0; i < m.n; i++) {
        const p = m.p[i];
        let nx = R.c * p.lnx - R.s * p.lny, ny = R.s * p.lnx + R.c * p.lny;
        const ppx = R.x + R.c * p.lpx - R.s * p.lpy, ppy = R.y + R.s * p.lpx + R.c * p.lpy;
        const pix = I.x + I.c * p.lix - I.s * p.liy, piy = I.y + I.s * p.lix + I.c * p.liy;
        const sep = (pix - ppx) * nx + (piy - ppy) * ny;
        if (sep + slop >= 0) continue;
        const C = Math.max(beta * (sep + slop), -maxC);
        if (m.flip) { nx = -nx; ny = -ny; }
        const rax = pix - a.x, ray = piy - a.y, rbx = pix - b.x, rby = piy - b.y;
        const rnA = rax * ny - ray * nx, rnB = rbx * ny - rby * nx;
        const K = a.im + b.im + a.iI * rnA * rnA + b.iI * rnB * rnB;
        if (K <= 0) continue;
        const imp = -C / K, Px = imp * nx, Py = imp * ny;
        if (!a.isStatic) {
          a.x -= a.im * Px; a.y -= a.im * Py; a.a -= a.iI * (rax * Py - ray * Px);
          a.c = Math.cos(a.a); a.s = Math.sin(a.a);
        }
        if (!b.isStatic) {
          b.x += b.im * Px; b.y += b.im * Py; b.a += b.iI * (rbx * Py - rby * Px);
          b.c = Math.cos(b.a); b.s = Math.sin(b.a);
        }
      }
    }
  }
}

