/* ============================================================
   Rigid-body engine
   Sequential impulses with warm starting, speculative contacts
   (anti-tunnelling), non-linear Gauss-Seidel position correction,
   post-solve restitution and island sleeping. Units: m, kg, s, y up.
   ============================================================ */
const PHYS = {
  h: 1 / 240,
  velIters: 10,
  posIters: 3,
  slop: 0.004,
  baumgarte: 0.2,
  maxCorrection: 0.06,
  restitutionThreshold: 0.9,
  specBase: 0.012,
  specMax: 0.5,
  maxLinSpeed: 70,
  maxAngSpeed: 50,
  angDamping: 0.05,
  sleepLin: 0.045,
  sleepAng: 0.09,
  sleepTime: 0.6,
};

class Shape {
  constructor(verts, noGround = false) {
    const n = verts.length;
    this.n = n;
