  const v1x = R.wv[2 * edge], v1y = R.wv[2 * edge + 1], v2x = R.wv[2 * i2], v2y = R.wv[2 * i2 + 1];
  const nx = R.wn[2 * edge], ny = R.wn[2 * edge + 1];

