+  ctx.stroke();
+
+  ctx.fillStyle = 'rgba(8,20,48,0.5)';
+  ctx.fillRect(-0.93, 0.25, f(0.93) + 0.93, 0.085);
+
+  ctx.beginPath();
+  ctx.moveTo(-1.48, 1.0);
+  ctx.quadraticCurveTo(-1.18, 1.34, -0.9, 1.39);
+  ctx.lineTo(-0.08, 1.395);
+  ctx.quadraticCurveTo(0.2, 1.38, 0.74, 1.01);
