+
+  if (sim.cabinHit > 25) {
+    const k = Math.min(1, sim.cabinHit / 150);
+    ctx.strokeStyle = `rgba(235,242,250,${(0.35 + 0.5 * k).toFixed(3)})`;
+    ctx.lineWidth = 0.9 * px;
+    ctx.beginPath();
+    for (let i = 0; i < 9; i++) {
+      const a = i * 0.71 + 0.3, l = (0.07 + ((i * 37) % 11) * 0.015) * (0.5 + k);
+      ctx.moveTo(0.3, 1.24);
