+
+function drawScaleBar(oy, S, w) {
+  const curbH = Math.max(10, 0.2 * S);
+  const x1 = w - 28, x0 = x1 - S, y = oy + curbH + 24;
+  if (y > view.h - 20) return;
+  ctx.strokeStyle = 'rgba(255,255,255,0.85)';
+  ctx.lineWidth = 2;
+  ctx.beginPath();
+  ctx.moveTo(x0, y - 5); ctx.lineTo(x0, y); ctx.lineTo(x1, y); ctx.lineTo(x1, y - 5);
+  ctx.moveTo((x0 + x1) / 2, y); ctx.lineTo((x0 + x1) / 2, y - 3);
+  ctx.stroke();
+  ctx.fillStyle = 'rgba(255,255,255,0.85)';
+  ctx.font = `600 10.5px ${MONO}`;
+  ctx.textAlign = 'right';
+  ctx.textBaseline = 'top';
+  ctx.fillText(`1 m \u00b7 ${FIXED.ppm} px/m \u00d7 ${(S / FIXED.ppm).toFixed(2)}`, x1, y + 5);
+  ctx.textAlign = 'left';
+}
