+  for (let i = 1; i < 4; i++) { const y = Math.round(pad + (i * (H - 2 * pad)) / 4) + 0.5; sctx.moveTo(pad, y); sctx.lineTo(W - pad, y); }
+  sctx.stroke();
+  sctx.setLineDash([3 * d, 3 * d]);
+  sctx.strokeStyle = 'rgba(255,198,41,0.35)';
+  sctx.beginPath(); sctx.moveTo(pad, Y(sim.P.carSpeed)); sctx.lineTo(W - pad, Y(sim.P.carSpeed)); sctx.stroke();
+  sctx.setLineDash([]);
+  if (sim.impactT >= 0) {
+    sctx.strokeStyle = 'rgba(255,90,78,0.8)';
+    sctx.beginPath(); sctx.moveTo(X(sim.impactT), pad); sctx.lineTo(X(sim.impactT), H - pad); sctx.stroke();
+  }
+  if (n > 1) {
+    sctx.beginPath();
+    sctx.moveTo(X(s[0]), Y(s[1]));
+    for (let i = 2; i < s.length; i += 2) sctx.lineTo(X(s[i]), Y(s[i + 1]));
+    sctx.strokeStyle = '#ffc629';
+    sctx.lineWidth = 1.6 * d;
+    sctx.lineJoin = 'round';
+    sctx.stroke();
+    sctx.lineTo(X(s[s.length - 2]), H - pad);
+    sctx.lineTo(X(s[0]), H - pad);
+    sctx.closePath();
+    sctx.fillStyle = 'rgba(255,198,41,0.1)';
+    sctx.fill();
+  }
+  el.sparkMax.textContent = `${vMax.toFixed(0)} m/s \u00b7 ${tMax.toFixed(1)} s`;
+}
+
+function showResult() {
+  const r = sim.result;
+  let cls = 'verdict-down', title = 'Wall demolished';
+  if (r.frac < 0.08) { cls = 'verdict-held'; title = 'Wall held'; }
+  else if (r.frac < 0.55) { cls = 'verdict-partial'; title = 'Partial collapse'; }
+  el.result.innerHTML =
+    `<h2 class="${cls}">${title}</h2>` +
+    `<p>${r.disp} / ${r.n} bricks displaced (${(r.frac * 100).toFixed(0)}%) &middot; furthest throw ${r.maxThrow.toFixed(1)} m<br>` +
+    `impact ${Math.abs(r.impactV).toFixed(1)} m/s &middot; peak ${r.peakG.toFixed(1)} g &middot; crush ${(r.crush * 100).toFixed(0)} cm &middot; ` +
+    `car moved ${r.travel.toFixed(1)} m after impact &middot; settled in ${r.t.toFixed(1)} s</p>`;
+  el.result.hidden = false;
+}
+function hideResult() { el.result.hidden = true; }
+
+function toggleSettings(open) {
+  const closed = open === undefined ? !el.settings.classList.contains('closed') : !open;
+  el.settings.classList.toggle('closed', closed);
+}
+
+$('btn-test').addEventListener('click', () => loadScene(true));
+$('btn-reset').addEventListener('click', () => loadScene(false));
+$('btn-defaults').addEventListener('click', () => {
+  Object.assign(settings, DEFAULTS);
+  for (const p of PARAMS) syncField(p.key);
+  settingsChanged();
+});
+$('btn-settings').addEventListener('click', () => toggleSettings());
+$('btn-collapse').addEventListener('click', () => toggleSettings(false));
+document.querySelectorAll('#timescale button').forEach(btn => {
+  btn.addEventListener('click', () => {
+    timeScale = Number(btn.dataset.ts);
+    document.querySelectorAll('#timescale button').forEach(x => x.classList.toggle('on', x === btn));
+    resetRate();
+  });
+});
+window.addEventListener('keydown', e => {
+  const t = e.target;
+  if (e.metaKey || e.ctrlKey || e.altKey) return;
+  if (t.tagName === 'INPUT' && t.type !== 'range') return;
+  if (t.tagName === 'BUTTON' && (e.code === 'Space' || e.key === 'Enter')) return;
+  if (e.code === 'Space') { e.preventDefault(); loadScene(true); }
+  else if (e.key === 'r' || e.key === 'R') loadScene(false);
+  else if (e.key === 's' || e.key === 'S') toggleSettings();
+});
+window.addEventListener('resize', resize);
+
+/* ============================================================
+   Main loop: fixed physics step, decoupled from frame rate
+   ============================================================ */
+let lastFrame = 0, uiTimer = 0;
+function frame(now) {
+  const dt = Math.min(0.1, Math.max(0, (now - lastFrame) / 1000));
+  lastFrame = now;
+  if (isRunning()) {
+    acc += dt * timeScale;
+    const t0 = performance.now();
+    let n = 0;
+    while (acc >= PHYS.h && isRunning()) {
+      simStep();
+      acc -= PHYS.h;
+      n++;
+      // Over budget: drop the backlog (the run slows down but stays step-for-step identical).
+      if (performance.now() - t0 > 24) { acc = Math.min(acc, PHYS.h); break; }
+    }
+    rateWin.sim += n * PHYS.h;
+    rateWin.real += dt;
+    if (rateWin.real > 0.5) { rateWin.value = rateWin.sim / rateWin.real; rateWin.sim = 0; rateWin.real = 0; }
+  } else {
+    acc = 0;
+  }
+  const dtVis = dt * timeScale;
+  fxUpdate(dtVis);
+  updateCamera(dt, dtVis);
+  render();
+  uiTimer += dt;
+  if (uiTimer > 0.1) { uiTimer = 0; updateTelemetry(); }
+  requestAnimationFrame(frame);
+}
+
+buildFields();
+sim = buildSim(applied);
+for (const p of PARAMS) syncField(p.key);
+if (window.innerWidth < 760) el.settings.classList.add('closed');
+resize();
+refreshPending();
+updateTelemetry();
+requestAnimationFrame(t => { lastFrame = t; frame(t); });
 </script>
 </body>
 </html>

