const script = html.slice(html.indexOf('<script>') + 8, html.lastIndexOf('</script>'));
const cut = script.indexOf('/* ============================================================\n   Rendering');
const core = script.slice(0, cut);

const harness = `
${core}
function showResult() {}
function run(P, maxT) {
  sim = buildSim(P);
  const wallStartMaxDrift = Math.max(...sim.bricks.map(b => Math.hypot(b.x - b.x0, b.y - b.y0)));
  sim.phase = 'tow'; sim.car.sleeping = false; sim.car.sleepT = 0; sim.car.noSleep = true;
  const t0 = Date.now();
  let steps = 0;
  while ((sim.phase !== 'settled') && sim.t < maxT) { simStep(); steps++; }
  const ms = Date.now() - t0;
  let disp = 0, nan = 0, below = 0;
  for (const b of sim.bricks) {
    if (!Number.isFinite(b.x) || !Number.isFinite(b.y)) nan++;
    if (b.minY < -0.05) below++;
    if (isDisplaced(b)) disp++;
  }
  const hash = sim.bricks.reduce((h, b) => h + b.x * 1.3 + b.y * 7.1 + b.a * 0.37, 0) + sim.car.x;
  return { phase: sim.phase, t: +sim.t.toFixed(3), impactT: +sim.impactT.toFixed(3), impactV: +sim.impactV.toFixed(3),
    peakG: +sim.peakG.toFixed(2), crush: +sim.crush.toFixed(3), carX: +sim.car.x.toFixed(3), carAngleDeg: +(sim.car.a*180/Math.PI).toFixed(2),
    carVx: +sim.car.vx.toFixed(3), bricks: sim.bricks.length, disp, nan, below, wallStartMaxDrift: +wallStartMaxDrift.toFixed(5),
    hash: hash.toFixed(9), steps, msPerSimSec: +(ms / sim.t).toFixed(1) };
}
module.exports = { run, DEFAULTS };
