const { spawn } = require('child_process');
const fs = require('fs');
const path = require('path');

const dir = __dirname;
const shots = path.join(dir, '_shots');
fs.mkdirSync(shots, { recursive: true });
const W = +(process.argv[2] || 1440), H = +(process.argv[3] || 900);
const port = 9333;
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', [
  '--headless=new', `--remote-debugging-port=${port}`, `--user-data-dir=${path.join(dir, '_chrome')}`,
  `--window-size=${W},${H}`, '--no-first-run', '--no-default-browser-check', '--hide-scrollbars', 'about:blank',
], { stdio: 'ignore' });

const sleep = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  let targets;
  for (let i = 0; i < 50; i++) {
    try { targets = await (await fetch(`http://127.0.0.1:${port}/json`)).json(); if (targets.length) break; } catch {}
    await sleep(200);
  }
  const page = targets.find(t => t.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise(r => ws.addEventListener('open', r));
  let id = 0;
  const pending = new Map();
  const logs = [];
  ws.addEventListener('message', ev => {
    const msg = JSON.parse(ev.data);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
    if (msg.method === 'Runtime.exceptionThrown') logs.push('EXCEPTION ' + JSON.stringify(msg.params.exceptionDetails.exception?.description || msg.params.exceptionDetails.text));
    if (msg.method === 'Runtime.consoleAPICalled') logs.push(msg.params.type + ' ' + msg.params.args.map(a => a.value ?? a.description).join(' '));
    if (msg.method === 'Log.entryAdded') logs.push('LOG ' + msg.params.entry.level + ' ' + msg.params.entry.text);
  });
  const send = (method, params = {}) => new Promise(r => { const i = ++id; pending.set(i, r); ws.send(JSON.stringify({ id: i, method, params })); });
  const evalJs = async expr => (await send('Runtime.evaluate', { expression: expr, returnByValue: true })).result?.result?.value;
  const shot = async name => {
    const r = await send('Page.captureScreenshot', { format: 'png' });
    fs.writeFileSync(path.join(shots, name + '.png'), Buffer.from(r.result.data, 'base64'));
  };

  await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: W, height: H, deviceScaleFactor: 1, mobile: false });
  await send('Page.navigate', { url: 'file://' + path.join(dir, 'index.html') });
  await sleep(1200);
  const initial = await evalJs(`JSON.stringify({ title: document.title, h1: document.querySelector('h1').textContent,
    speed: settings.carSpeed, cols: settings.cols, rows: settings.rows, layers: settings.layers, mass: settings.brickMass,
    bricks: sim.bricks.length, phase: sim.phase, S: view.S })`);
  console.log('initial', initial);
  await shot(`${W}_0_initial`);

  await evalJs(`document.getElementById('btn-test').click()`);
  const plan = [[450, 'tow'], [700, 'impact'], [1100, 'crash'], [2500, 'debris'], [7000, 'settled']];
  let tPrev = 0;
  for (const [t, name] of plan) {
    await sleep(t - tPrev); tPrev = t;
    await shot(`${W}_${t}_${name}`);
    console.log(name, await evalJs(`JSON.stringify({ phase: sim.phase, t: +sim.t.toFixed(2), v: +sim.car.vx.toFixed(2), moving: document.getElementById('t-moving').textContent, disp: document.getElementById('t-disp').textContent, rate: document.getElementById('t-rate').textContent, parts: fx.parts.length })`));
  }
  console.log('result', await evalJs(`document.getElementById('result').hidden ? 'hidden' : document.getElementById('result').innerText`));
  console.log('browser hash', await evalJs(`(sim.bricks.reduce((h, b) => h + b.x * 1.3 + b.y * 7.1 + b.a * 0.37, 0) + sim.car.x).toFixed(9) + ' t=' + sim.t.toFixed(3)`));
  await evalJs(`document.getElementById('btn-settings').click()`);
  await sleep(900);
  await shot(`${W}_panel_closed`);
  console.log('console:', logs.length ? logs.join('\n') : '(clean)');
  ws.close();
  chrome.kill();
  process.exit(0);
})().catch(e => { console.error(e); chrome.kill(); process.exit(1); });

