function showResult() {
  const r = sim.result;
  let cls = 'verdict-down', title = 'Wall demolished';
  if (r.fallenFrac < 0.1) {
    cls = 'verdict-held';
    title = r.frac < 0.1 ? 'Wall held' : 'Wall shoved, still standing';
  } else if (r.fallenFrac < 0.6) {
    cls = 'verdict-partial'; title = 'Partial collapse';
  }
  el.result.innerHTML =
    `<h2 class="${cls}">${title}</h2>` +
    `<p>${r.fallen} / ${r.n} bricks fallen (${(r.fallenFrac * 100).toFixed(0)}%) &middot; ${r.disp} displaced &middot; furthest throw ${r.maxThrow.toFixed(1)} m<br>` +
    `impact ${Math.abs(r.impactV).toFixed(1)} m/s &middot; peak ${r.peakG.toFixed(1)} g &middot; crush ${(r.crush * 100).toFixed(0)} cm &middot; ` +
    `car moved ${r.travel.toFixed(1)} m after impact &middot; settled in ${r.t.toFixed(1)} s</p>`;
  el.result.hidden = false;
}

